def before_update(self, introspection_data, node_info, node_patches, ports_patches, **kwargs):
    hints = node_info.node().properties.get('root_device')
    if not hints:
        LOG.debug('Root device hints are not provided', node_info=node_info, data=introspection_data)
        return
    inventory = introspection_data.get('inventory')
    if not inventory:
        raise utils.Error(_('Root device selection requires ironic-python-agent as an inspection ramdisk'), node_info=node_info, data=introspection_data)
    disks = inventory.get('disks', [])
    if not disks:
        raise utils.Error(_('No disks found'), node_info=node_info, data=introspection_data)
    for disk in disks:
        properties = disk.copy()
        properties['size'] //= units.Gi
        for (name, value) in hints.items():
            actual = properties.get(name)
            if actual != value:
                LOG.debug('Disk %(disk)s does not satisfy hint %(name)s=%(value)s, actual value is %(actual)s', {'disk': disk.get('name'), 'name': name, 'value': value, 'actual': actual}, node_info=node_info, data=introspection_data)
                break
        else:
            LOG.debug('Disk %(disk)s of size %(size)s satisfies root device hints', {'disk': disk.get('name'), 'size': disk['size']}, node_info=node_info, data=introspection_data)
            introspection_data['root_disk'] = disk
            return
    raise utils.Error(_('No disks satisfied root device hints'), node_info=node_info, data=introspection_data)

