def compile(self, lang):
    dest = self.translated_base_path(lang)
    if not self.is_translation_available(lang) and (not self.config['SHOW_UNTRANSLATED_POSTS']):
        return
    LocaleBorg().set_locale(lang)
    self.compile_html(self.translated_source_path(lang), dest, self.is_two_file, self, lang)
    Post.write_depfile(dest, self._depfile[dest], post=self, lang=lang)
    signal('compiled').send({'source': self.translated_source_path(lang), 'dest': dest, 'post': self, 'lang': lang})
    if self.publish_later:
        LOGGER.notice('{0} is scheduled to be published in the future ({1})'.format(self.source_path, self.date))

def test_decimal_builtins_2(self):
    d = ibis.literal('5.245')
    dc = d.cast('decimal(12,5)')
    cases = [(dc % 5, Decimal('0.245')), (dc.fillna(0), Decimal('5.245')), (dc.exp(), 189.6158), (dc.log(), 1.65728), (dc.log2(), 2.39094), (dc.log10(), 0.71975), (dc.sqrt(), 2.29019), (dc.zeroifnull(), Decimal(5.245)), (-dc, Decimal('-5.245'))]
    for (expr, expected) in cases:
        result = self.con.execute(expr)

        def approx_equal(a, b, eps=0.0001):
            assert abs(a - b) < eps
        approx_equal(result, expected)

